                    case DalvikType::STRING_REF:
                        out += el->string_val; break;
                    case DalvikType::INT32:
                        out += std::to_string(el->int_val); break;
                    case DalvikType::INT64:
                        out += std::to_string(el->long_val); break;
                    case DalvikType::BOOLEAN:
                        out += el->bool_val ? "true" : "false"; break;
                    case DalvikType::FLOAT64:
                        out += std::to_string(el->double_val); break;
                    case DalvikType::NULL_REF:
                        out += "null"; break;
