            throw_deferred("Ljava/io/FileNotFoundException;",
                           "assets/" + asset_name + " (no entry)", "ASSET-FD");
            result = DalvikValue::make_null();
            status = ApiCallTrace::Status::IMPLEMENTED;
            return true;
